"use client"

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import {
  CheckCircle,
  AlertCircle,
  User,
  Globe,
  MapPin,
  Briefcase,
  Mail,
  Phone,
} from "lucide-react";
import Layout from "../Layout";

export default function EditIntern() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [formData, setFormData] = useState({
    CFF: "",
    First_Name: "",
    Last_Name: "",
    Gender: "",
    Nationality: "",
    Sector: "",
    hometown: "",
    email: "",
    emplacement: "",
    phoneNumber: "",
    parentPhoneNumber: "",
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [emplacementError, setEmplacementError] = useState("");

  useEffect(() => {
    const fetchIntern = async () => {
      setIsLoading(true);
      const token = localStorage.getItem("token");
      if (!token) {
        setError("Authentication required. Please log in.");
        setIsLoading(false);
        return;
      }

      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/interns/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        setFormData(response.data.data);
      } catch (error) {
        const errorMsg =
          error.response?.data?.message || "Failed to fetch intern data.";
        setError(errorMsg);
      } finally {
        setIsLoading(false);
      }
    };
    fetchIntern();
  }, [id]);

  const validateEmplacement = async (value) => {
    const prefix = formData.Gender === "Male" ? "RB" : "RG";
    const regex = new RegExp(`^${prefix}(1[0-6]|[1-9]),([1-4])$`);

    if (!value) {
      setEmplacementError("L'emplacement est requis.");
      return false;
    }

    if (!regex.test(value)) {
      setEmplacementError(`L'emplacement doit être au format ${prefix}[1-16],[1-4] (ex: ${prefix}5,3).`);
      return false;
    }

    try {
      const token = localStorage.getItem("token");
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/interns/check-emplacement/${value}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (response.data.taken && value !== formData.emplacement) {
        setEmplacementError(`L'emplacement ${value} est déjà pris.`);
        return false;
      } else {
        setEmplacementError("");
        return true;
      }
    } catch (err) {
      setEmplacementError("Erreur lors de la vérification de l'emplacement: " + (err.response?.data?.message || err.message));
      return false;
    }
  };

  const handleChange = async (e) => {
    const { name, value } = e.target;
    const updatedValue = name === "emplacement" ? value.toUpperCase() : value;
    setFormData({ ...formData, [name]: updatedValue });

    if (name === "emplacement") {
      await validateEmplacement(updatedValue);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");
    const role = "Deputydirector";

    const isEmplacementValid = await validateEmplacement(formData.emplacement);
    if (!isEmplacementValid) {
      setError("Veuillez corriger l'erreur d'emplacement avant de soumettre.");
      setIsSubmitting(false);
      return;
    }

    try {
      const response = await axios.put(
        `${process.env.REACT_APP_API_URL}/api/interns/${id}`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: role,
          },
        }
      );

      if (response.data.success) {
        setSuccess("Stagiaire mis à jour avec succès !");
        setTimeout(() => navigate("/interns"), 2000);
      } else {
        setError("Échec de la mise à jour du stagiaire.");
      }
    } catch (err) {
      setError(err.response?.data?.message || "Une erreur s'est produite.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <svg
          className="animate-spin h-8 w-8 text-gray-500"
          xmlns="http://www.w3.org/2000/svg"
          fill="none"
          viewBox="0 0 24 24"
        >
          <circle
            className="opacity-25"
            cx="12"
            cy="12"
            r="10"
            stroke="currentColor"
            strokeWidth="4"
          />
          <path
            className="opacity-75"
            fill="currentColor"
            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
          />
        </svg>
      </div>
    );
  }

  return (
    <Layout>
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-xl shadow-xl overflow-hidden">
          <div className="bg-primary text-primary-foreground p-6">
            <h2 className="text-2xl font-bold tracking-tight">Modifier un stagiaire</h2>
            <p className="text-primary-foreground/80 mt-1">Mettez à jour les détails du stagiaire</p>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${error ? "border-red-500" : "border-green-500"} flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6">
            <div className="space-y-8">
              <div>
                <h3 className="text-lg font-medium text-gray-900 border-b pb-2">Informations personnelles</h3>
                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">CFF</label>
                    <input
                      type="text"
                      name="CFF"
                      value={formData.CFF}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      required
                      disabled
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Prénom</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="First_Name"
                        value={formData.First_Name}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <User className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Nom de famille</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="Last_Name"
                        value={formData.Last_Name}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <User className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Genre</label>
                    <select
                      name="Gender"
                      value={formData.Gender}
                      onChange={handleChange}
                      className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      required
                    >
                      <option value="">Sélectionnez le genre</option>
                      <option value="Male">Homme</option>
                      <option value="Female">Femme</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Nationalité</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="Nationality"
                        value={formData.Nationality}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <Globe className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Secteur</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="Sector"
                        value={formData.Sector}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <Briefcase className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Numéro de téléphone</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="phoneNumber"
                        value={formData.phoneNumber}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      />
                      <Phone className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Numéro de téléphone du parent</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="parentPhoneNumber"
                        value={formData.parentPhoneNumber}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                      />
                      <Phone className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2 md:col-span-2 lg:col-span-3">
                    <label className="block text-sm font-medium text-gray-700">Ville d'origine</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="hometown"
                        value={formData.hometown}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <MapPin className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Email</label>
                    <div className="relative">
                      <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        required
                      />
                      <Mail className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-gray-700">Emplacement</label>
                    <div className="relative">
                      <input
                        type="text"
                        name="emplacement"
                        value={formData.emplacement}
                        onChange={handleChange}
                        className="block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-primary focus:border-primary"
                        placeholder={formData.Gender === "Male" ? "ex: RB5,3" : "ex: RG5,3"}
                        required
                      />
                      <MapPin className="h-5 w-5 text-gray-400 absolute right-3 top-1/2 transform -translate-y-1/2" />
                    </div>
                    {emplacementError && (
                      <p className="text-sm text-red-600">{emplacementError}</p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-8 flex justify-end">
              <button
                type="button"
                onClick={() => navigate("/interns")}
                className="px-5 py-3 border border-gray-300 text-gray-700 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary mr-3"
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={isSubmitting || emplacementError}
                className={`px-5 py-3 bg-primary text-primary-foreground rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary flex items-center ${
                  isSubmitting || emplacementError ? "opacity-50 cursor-not-allowed" : "hover:bg-primary/90"
                }`}
              >
                {isSubmitting ? (
                  <>
                    <svg
                      className="animate-spin -ml-1 mr-2 h-4 w-4 text-white"
                      xmlns="http://www.w3.org/2000/svg"
                      fill="none"
                      viewBox="0 0 24 24"
                    >
                      <circle
                        className="opacity-25"
                        cx="12"
                        cy="12"
                        r="10"
                        stroke="currentColor"
                        strokeWidth="4"
                      ></circle>
                      <path
                        className="opacity-75"
                        fill="currentColor"
                        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                      ></path>
                    </svg>
                    Traitement...
                  </>
                ) : (
                  "Mettre à jour le stagiaire"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </Layout>
  );
}
